(() => {
  const STAMP='2026-09-16T17:00:00+02:00';
  const CUTOFF='2026-05-16';
  const CHECKED=new Set(['CAT','JBL','LMT','MCD','AMZN','MEDP','NTAP','RNG']);
  const CHANGED=new Set(['RNG']);
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const fmt=v=>new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)).replace(',',' ·');
  async function ready(){for(let i=0;i<60;i++){try{if(Array.isArray(holdings)&&holdings.length===12&&typeof renderCards==='function'&&typeof renderDetail==='function')return true}catch(_){}await sleep(100)}return false}
  function apply(){
    window.marketAgentUpdateMeta={contentUpdatedAt:STAMP,lastSuccessfulRunAt:STAMP,status:'partial',marketStatus:'US open'};
    holdings.forEach(h=>{if(!CHECKED.has(h.id))return;h.analysts=(h.analysts||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=CUTOFF);h.insiders=(h.insiders||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=CUTOFF);h.lastCheckedAt=STAMP;h.changedSections=[];h.updateStatus='checked';delete h.updateTag});
    const rng=holdings.find(h=>h.id==='RNG');if(rng){const t=(rng.triggers||[]).find(x=>x.date==='2026-09-15'&&/Piper Sandler Growth Frontiers/.test(x.title||''));if(t){t.status='abgeschlossen';t.background='RingCentral-Management präsentierte am 15.09. auf der Piper Sandler Growth Frontiers Conference. Der zuvor anstehende Termin ist damit abgeschlossen; weitere belastbare neue Unternehmensmeldung wurde bis zum Lauf nicht verifiziert.';}rng.lastChangedAt=STAMP;rng.changedSections=['Termin/Trigger'];rng.updateStatus='updated';rng.updateTag='AKTUALISIERT'}
  }
  function badge(el,label){if(!el||el.querySelector('.update-badge'))return;const b=document.createElement('span');b.className='update-badge';b.textContent=label;el.prepend(b)}
  function mark(){const chip=document.getElementById('content-state-chip'),text=document.getElementById('content-state');if(chip&&text){text.textContent=`Inhalte: ${fmt(STAMP)}`;chip.classList.remove('status-ok','status-error','status-closed');chip.classList.add('status-partial');chip.title='US-Börsen regulär geöffnet. Acht US-Werte geprüft. Holdings-Datei nicht erreichbar – letzter bestätigter Bestand verwendet. 12er-Bestand gegen Dashboard und Marktdaten-Symbole abgeglichen; keine Position entfernt.'}document.querySelectorAll('.update-badge').forEach(e=>e.remove());document.querySelectorAll('.holding').forEach(c=>{c.classList.remove('content-changed','content-partial');const h=holdings.find(x=>x.id===c.dataset.id);if(CHANGED.has(c.dataset.id)){c.classList.add('content-changed');c.title=`Heute inhaltlich aktualisiert · ${(h?.changedSections||[]).join(', ')}`}else if(h&&CHECKED.has(h.id))c.title=`Letzte Inhaltsprüfung: ${fmt(STAMP)} · Keine inhaltliche Änderung`});if(selected==='RNG')document.querySelectorAll('#tab-events .trigger').forEach(e=>{/Piper Sandler Growth Frontiers/.test(e.textContent||'')&&badge(e.querySelector('.item-top'),'AKTUALISIERT')});const footer=document.querySelector('footer.shell');if(footer)footer.textContent='Market Agent · Datenstand 16.09.2026 · 17:00 · Quellen in jedem Eintrag'}
  async function boot(){if(!(await ready()))return;apply();renderCards();renderDetail();mark();[500,1500,4000,8000].forEach(ms=>setTimeout(()=>{try{renderCards();renderDetail();mark()}catch(_){}},ms));document.addEventListener('click',e=>{if(e.target.closest('.holding,.tab,.filter'))setTimeout(mark,0)});window.addEventListener('pageshow',()=>setTimeout(mark,0))}boot();
})();